@startuml

enum Suit {
  DIAMONDS
  HEARTS
  SPADES
  CLUBS
}

enum CardHeight {
  LOWER
  EQUAL
  HIGHER
}

enum SoloType {
  TRUMP
  JACK
  QUEEN
}

abstract class CardGame {
  + id : string
}

class Game extends CardGame {
}

class Player {
  + id : string
}

class Deck {
  + id : string
}

class Card {
  + id : string
  + compareHeight(other : Card) : CardHeight
}

class ScoringTable {
  + id : string
}

class Round {
  + id : string
  + pointValue : int
}

class JackRound {}

class SoloRound {
  + soloType : SoloType
}

class MandatorySoloRound extends SoloRound {}

class WinningPlayer {
}

class SoloPlayer {
}

Game "1" *-- "4" Player
Game "1" *-- "1" Deck
Game "1" *-- "1" ScoringTable
Deck "1" *-- "0..48" Card
ScoringTable "1" *-- "*" Round
Round "1" *-- "*" WinningPlayer
Round "1" -- "0..1" SoloPlayer
Round "0..1" -- "0..1" JackRound
Round "0..1" -- "0..1" SoloRound

@enduml

